input.command:
mkdir -p internal/password && cat > internal/password/password.go <<'EOF'
// Package password provides password hashing and verification using bcrypt.
package password

import (
	"errors"

	"golang.org/x/crypto/bcrypt"
)

// Cost is the bcrypt work factor used for new hashes.
const Cost = 12

// ErrMismatch is returned when a password does not match its hash.
var ErrMismatch = errors.New("password: mismatch")

// Hash returns a bcrypt hash of the given password.
func Hash(plain string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(plain), Cost)
	if err != nil {
		return "", err
	}
	return string(h), nil
}

// Verify reports whether plain matches the stored bcrypt hash.
func Verify(hash, plain string) error {
	err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(plain))
	if errors.Is(err, bcrypt.ErrMismatchedHashAndPassword) {
		return ErrMismatch
	}
	return err
}
EOF
cat > internal/password/password_test.go <<'EOF'
package password

import (
	"errors"
	"testing"
)

func TestHashAndVerify(t *testing.T) {
	h, err := Hash("correct horse battery staple")
	if err != nil {
		t.Fatal(err)
	}
	if err := Verify(h, "correct horse battery staple"); err != nil {
		t.Fatalf("expected match, got %v", err)
	}
	if err := Verify(h, "wrong"); !errors.Is(err, ErrMismatch) {
		t.Fatalf("expected ErrMismatch, got %v", err)
	}
}
EOF
mkdir -p cmd/app && cat > cmd/app/main.go <<'EOF'
package main

import (
	"fmt"
	"log"

	"example.com/app/internal/password"
)

func main() {
	h, err := password.Hash("s3cret")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("hash:", h)
	fmt.Println("verify:", password.Verify(h, "s3cret") == nil)
}
EOF
printf '/bin/\n' > .gitignore
go mod tidy && go vet ./... && go test ./... && go run ./cmd/app && cat go.mod

